-- 04-configuration-tables: 38 records from the uploaded workbook, not live Sheets.
-- DB Browser: save pending edits first. Execute this WHOLE file, then Write Changes.
-- SAVEPOINT supports DB Browser's existing transaction; there is no BEGIN/COMMIT.
-- Identical reruns do nothing. Conflicts roll back the transaction instead of overwriting.
PRAGMA foreign_keys=ON;
SAVEPOINT afl_import_4;
CREATE TEMP TABLE afl_import_4 AS SELECT id, settings_version_id, table_key, schema_version, units_json, values_json, is_active FROM configuration_tables WHERE 0;
CREATE TEMP TABLE afl_import_4_guard(ok INTEGER);
CREATE TEMP TRIGGER afl_import_4_check BEFORE INSERT ON afl_import_4_guard
BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM leagues WHERE id='36c6e53f-7be2-5a94-84a8-0df871aae9fd' AND name='AFL') THEN RAISE(ROLLBACK,'Missing expected AFL league record.') END;
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM settings_versions WHERE id='05328eb3-a56b-5792-b238-e05c32377adc' AND league_id='36c6e53f-7be2-5a94-84a8-0df871aae9fd' AND content_hash='5fe3cbed093c254ca3e00c4bc2d73dc6fe9778839eefb35ae5cf7e705bdd90ea' AND status='draft') THEN RAISE(ROLLBACK,'Import matching draft settings version (03) first.') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM afl_import_4 i JOIN configuration_tables t ON t.id=i.id WHERE t.settings_version_id IS NOT i.settings_version_id OR t.table_key IS NOT i.table_key OR t.schema_version IS NOT i.schema_version OR t.units_json IS NOT i.units_json OR t.values_json IS NOT i.values_json OR t.is_active IS NOT i.is_active) THEN RAISE(ROLLBACK,'Existing ID has different data; no records overwritten.') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM afl_import_4 i JOIN configuration_tables t ON t.settings_version_id=i.settings_version_id AND t.table_key=i.table_key WHERE t.id<>i.id) THEN RAISE(ROLLBACK,'An existing natural key uses another ID; reconcile before importing.') END;
END;
DROP TRIGGER afl_import_4_check;
DROP TABLE afl_import_4_guard;
DROP TABLE afl_import_4;
RELEASE SAVEPOINT afl_import_4;
PRAGMA foreign_key_check;
SELECT 'configuration_tables' AS imported_table, COUNT(*) AS reviewed_records_present FROM configuration_tables WHERE id IN ('b4f638fd-4161-5c36-a1d9-9569a3935907', '8ff98b1b-f7ed-5650-bc44-e7f6bf2a4f11', 'e788cdfe-b00d-5ec4-a262-2452f8266b7f', '5a79a5e0-73e6-5c3b-9091-4522ec66bb18', '737c9549-808e-52ac-8898-857474e88cb3', '0f60e5a2-6a35-56c8-93cb-31ba3e303462', 'ffa8c864-6e78-5a44-9dfd-8106b5776542', 'd264bf34-2090-5334-a64c-11a6d12bfb44', '0ada119e-a9a8-5b05-8925-d98bc593f7f7', 'ec7282ba-a0c2-5c3f-87e3-a01eaff9b74d', 'd88f0645-0243-5393-8cd2-1248784c06a3', 'b75dfe5e-8ea6-5d6b-8d94-2868201a379a', '16a4ea6e-320c-57f9-9079-69ec6651cb6a', '6adfad42-2e1d-57c9-965f-c950329777be', '3ca2a1ef-edd3-5c09-b7d1-b8f7b520c3eb', '3a2ed6a4-fbc9-5959-8cec-2fd3de24c7dd', 'f62fc996-3b45-51fb-9147-1263470ba67c', '704232cf-81ae-557f-96f5-5fb0c4ad4fe7', 'b495531d-f7eb-5908-9cb5-5dc3da028050', 'e402a488-abb0-5889-9c1a-91218585fe01', 'd3ee9f50-b297-5c5e-a77e-e24697aaf972', '879d9bb2-5626-5cca-a20c-1890d2f4068c', '27936f50-5fb5-520b-9fd6-a5478cba46c6', '722413ec-1109-580a-84c0-4d5cb37eb732', 'a3169400-09e2-5605-809e-42b5ce156ed3', '70d62d1e-639c-58b0-bb3e-4edd6062be85', '5587c4fc-c8fd-5b84-8368-a1f3ab712bb5', 'b42e2622-7122-5ddd-91fc-53c46fdafe7d', '5e473116-d27b-5031-b998-572544e8d391', 'c0a8f350-ea97-58ea-ae71-e30da8d34d40', 'cb58b320-0200-5699-85f5-de105bc019d5', '2fe01ced-1089-50ff-b4c6-79b029be0fa6', '324bf127-767a-59c6-94b2-08788fccce44', '68e04ffd-b53b-544e-81e8-fbc65917fed2', '1cd0b724-53fc-5208-8dec-fda2f702119c', '9c6ea6b5-b4cb-5349-8ff6-464721b5de46', 'e535a75c-6f0b-5142-afc1-1628a7159714', 'af465ec1-5da0-5b09-a4af-9e36dc8fb522');
